export const MAGICDRAW_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/magicdraw-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getMagicDrawStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(MAGICDRAW_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
